}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.2rem;
    background: #edf2f4;
    border: 1px solid #d4d8e0;
    border-radius: 12px;
    padding: 0.15rem 0.5rem;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background-color 0.15s;
}

.reaction-badge:hover {
    background: #d4d8e0;
}

.reaction-count {
    font-size: 0.75rem;
    color: #4a4e69;
}

.thread-link {
    background: none;
    border: none;
    color: #3a86ff;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.2rem 0;
    margin-top: 0.3rem;
    font-weight: 500;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: 0.3rem;
    right: 0.5rem;
    display: flex;
    gap: 0.3rem;
    background: white;
    border: 1px solid #d4d8e0;
    border-radius: 6px;
    padding: 0.2rem 0.3rem;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1);
}

.action-btn {
    background: none;
    border: none;
    font-size: 0.75rem;
