    padding: 0.25rem 0.5rem;
    border-radius: 4px;
    transition: background-color 0.1s;
}

.action-btn:hover {
    background-color: #edf2f4;
}

.emoji-picker {
    display: flex;
    gap: 0.2rem;
    background: white;
    border: 1px solid #d4d8e0;
    border-radius: 8px;
