    font-size: 0.9rem;
    color: #2b2d42;
    line-height: 1.4;
    white-space: pre-wrap;
}

.message-reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
    margin-top: 0.4rem;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
