toolArgs.file_text:
.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: white;
}

.message-area-header {
    padding: 0.8rem 1.2rem;
    border-bottom: 1px solid #e4e7eb;
    flex-shrink: 0;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #1a1a2e;
}

.message-area-header p {
    margin: 0.2rem 0 0;
    font-size: 0.8rem;
    color: #8d99ae;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
}

.loading-indicator {
    text-align: center;
    padding: 0.5rem;
    font-size: 0.8rem;
    color: #8d99ae;
}

.message-input-area {
    display: flex;
    align-items: flex-end;
    gap: 0.5rem;
    padding: 0.8rem 1.2rem;
    border-top: 1px solid #e4e7eb;
    flex-shrink: 0;
}

.message-input {
    flex: 1;
    resize: none;
    border: 1px solid #d4d8e0;
    border-radius: 8px;
    padding: 0.6rem 0.8rem;
    font-size: 0.9rem;
    font-family: inherit;
    min-height: 2.4rem;
    max-height: 6rem;
    outline: none;
    transition: border-color 0.15s;
}

.message-input:focus {
    border-color: #3a86ff;
}

.send-btn {
    background-color: #3a86ff;
    color: white;
    border: none;
    border-radius: 8px;
    padding: 0.6rem 1.2rem;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.15s;
    white-space: nowrap;
}

.send-btn:hover:not(:disabled) {
    background-color: #2672e6;
}

.send-btn:disabled {
    background-color: #a8c4f0;
    cursor: not-allowed;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #8d99ae;
    font-size: 1rem;
}

