.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: white;
    border-left: 1px solid #e4e7eb;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.8rem 1rem;
    border-bottom: 1px solid #e4e7eb;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #1a1a2e;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #8d99ae;
    padding: 0.2rem 0.4rem;
    border-radius: 4px;
    transition: background-color 0.1s;
}

.close-btn:hover {
    background-color: #edf2f4;
    color: #2b2d42;
}

.thread-root-message {
    padding: 0.8rem 1rem;
    background: #f8f9fb;
    border-bottom: 1px solid #e4e7eb;
    flex-shrink: 0;
}

.root-author {
    font-weight: 700;
    font-size: 0.85rem;
    color: #1a1a2e;
    margin-bottom: 0.2rem;
}

.root-content {
    font-size: 0.85rem;
    color: #4a4e69;
    line-height: 1.3;
    white-space: pre-wrap;
}

.thread-divider {
    padding: 0.4rem 1rem;
    font-size: 0.75rem;
    color: #8d99ae;
    border-bottom: 1px solid #e4e7eb;
    flex-shrink: 0;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
}

.thread-reply {
    padding: 0.5rem 1rem;
}

.reply-header {
    display: flex;
    align-items: baseline;
    gap: 0.4rem;
    margin-bottom: 0.15rem;
}

.reply-author {
    font-weight: 700;
    font-size: 0.82rem;
    color: #1a1a2e;
}

.reply-time {
    font-size: 0.7rem;
    color: #8d99ae;
}

.reply-content {
    font-size: 0.85rem;
    color: #2b2d42;
    line-height: 1.3;
    white-space: pre-wrap;
}

.thread-input-area {
    display: flex;
    align-items: flex-end;
    gap: 0.4rem;
    padding: 0.6rem 0.8rem;
    border-top: 1px solid #e4e7eb;
    flex-shrink: 0;
}

.thread-input {
    flex: 1;
    resize: none;
    border: 1px solid #d4d8e0;
    border-radius: 6px;
    padding: 0.5rem 0.6rem;
    font-size: 0.82rem;
    font-family: inherit;
    min-height: 2rem;
    max-height: 4rem;
    outline: none;
    transition: border-color 0.15s;
}

.thread-input:focus {
    border-color: #3a86ff;
}

.reply-btn {
    background-color: #3a86ff;
    color: white;
    border: none;
    border-radius: 6px;
    padding: 0.5rem 0.8rem;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.15s;
}

.reply-btn:hover:not(:disabled) {
    background-color: #2672e6;
}

.reply-btn:disabled {
    background-color: #a8c4f0;
    cursor: not-allowed;
}

